// ─── File: src/main/java/com/bank/succession/service/SuccessionService.java ───
package com.bank.succession.service;

import com.bank.succession.dto.SuccessionReport;
import com.bank.succession.model.Employee;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class SuccessionService {

    private final List<Employee> employees = List.of(
        new Employee("E001", "Rajesh Kumar",  "TRADING",    "M", 35, 8,  new BigDecimal("1200000")),
        new Employee("E002", "Priya Sharma",  "RISK",       "F", 28, 3,  new BigDecimal("1000000")),
        new Employee("E003", "Amit Patel",    "TRADING",    "M", 52, 22, new BigDecimal("1500000")),
        new Employee("E004", "Deepa Reddy",   "OPERATIONS", "F", 45, 18, new BigDecimal("900000")),
        new Employee("E005", "Vikram Singh",  "RISK",       "M", 55, 25, new BigDecimal("1800000")),
        new Employee("E006", "Neha Gupta",    "TRADING",    "F", 32, 5,  new BigDecimal("1100000")),
        new Employee("E007", "Suresh Iyer",   "OPERATIONS", "M", 58, 30, new BigDecimal("1400000")),
        new Employee("E008", "Kavita Joshi",  "RISK",       "F", 41, 15, new BigDecimal("950000")),
        new Employee("E009", "Rohit Mehta",   "COMPLIANCE", "M", 48, 20, new BigDecimal("1300000")),
        new Employee("E010", "Anita Desai",   "COMPLIANCE", "F", 37, 10, new BigDecimal("1050000"))
    );

    public SuccessionReport generateReport() {

        // ═══ 1. OLDEST EMPLOYEE overall ═══
        String oldest = employees.stream()
            .max(Comparator.comparingInt(Employee::age))
            .map(e -> e.name() + " (age " + e.age() + ", " + e.department() + ")")
            .orElse("No employees");
        log.info("Oldest: {}", oldest);

        // ═══ 2. YOUNGEST FEMALE overall ═══
        String youngestFemale = employees.stream()
            .filter(e -> "F".equals(e.gender()))
            .min(Comparator.comparingInt(Employee::age))
            .map(e -> e.name() + " (age " + e.age() + ", " + e.department() + ")")
            .orElse("No female employees");
        log.info("Youngest female: {}", youngestFemale);

        // ═══ 3. LONGEST-SERVING overall ═══
        String longestServing = employees.stream()
            .max(Comparator.comparingInt(Employee::yearsOfService))
            .map(e -> e.name() + " (" + e.yearsOfService() + " years, " + e.department() + ")")
            .orElse("No employees");
        log.info("Longest-serving: {}", longestServing);

        // ═══ 4. OLDEST PER DEPARTMENT ═══
        Map<String, String> oldestPerDept = employees.stream()
            .collect(Collectors.groupingBy(Employee::department,
                Collectors.collectingAndThen(
                    Collectors.maxBy(Comparator.comparingInt(Employee::age)),
                    opt -> opt.map(e -> e.name() + " (age " + e.age() + ")").orElse("N/A"))));
        log.info("Oldest per dept: {}", oldestPerDept);

        // ═══ 5. YOUNGEST FEMALE PER DEPARTMENT ═══
        Map<String, String> youngestFemalePerDept = employees.stream()
            .filter(e -> "F".equals(e.gender()))
            .collect(Collectors.groupingBy(Employee::department,
                Collectors.collectingAndThen(
                    Collectors.minBy(Comparator.comparingInt(Employee::age)),
                    opt -> opt.map(e -> e.name() + " (age " + e.age() + ")").orElse("N/A"))));
        log.info("Youngest female per dept: {}", youngestFemalePerDept);

        // ═══ 6. LONGEST-SERVING PER DEPARTMENT ═══
        Map<String, String> longestPerDept = employees.stream()
            .collect(Collectors.groupingBy(Employee::department,
                Collectors.collectingAndThen(
                    Collectors.maxBy(Comparator.comparingInt(Employee::yearsOfService)),
                    opt -> opt.map(e -> e.name() + " (" + e.yearsOfService() + " yrs)").orElse("N/A"))));
        log.info("Longest-serving per dept: {}", longestPerDept);

        return new SuccessionReport(oldest, youngestFemale, longestServing,
            oldestPerDept, youngestFemalePerDept, longestPerDept);
    }
}
