package com.bank.succession.service;

import com.bank.succession.model.Employee;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class MinMaxEmployeeTest {

    List<Employee> emps = List.of(
        new Employee("E1", "Rajesh", "TRADING", "M", 35, 8, BigDecimal.valueOf(1200000)),
        new Employee("E2", "Priya", "RISK", "F", 28, 3, BigDecimal.valueOf(1000000)),
        new Employee("E3", "Amit", "TRADING", "M", 52, 22, BigDecimal.valueOf(1500000)),
        new Employee("E4", "Deepa", "RISK", "F", 45, 18, BigDecimal.valueOf(900000)),
        new Employee("E5", "Suresh", "OPERATIONS", "M", 58, 30, BigDecimal.valueOf(1400000))
    );

    @Test
    void oldestOverall() {
        Optional<Employee> oldest = emps.stream().max(Comparator.comparingInt(Employee::age));
        assertThat(oldest).isPresent();
        assertThat(oldest.get().name()).isEqualTo("Suresh");
        assertThat(oldest.get().age()).isEqualTo(58);
    }

    @Test
    void youngestFemale() {
        Optional<Employee> youngest = emps.stream()
            .filter(e -> "F".equals(e.gender()))
            .min(Comparator.comparingInt(Employee::age));
        assertThat(youngest).isPresent();
        assertThat(youngest.get().name()).isEqualTo("Priya");
    }

    @Test
    void longestServing() {
        Optional<Employee> longest = emps.stream()
            .max(Comparator.comparingInt(Employee::yearsOfService));
        assertThat(longest.get().name()).isEqualTo("Suresh");
        assertThat(longest.get().yearsOfService()).isEqualTo(30);
    }

    @Test
    void oldestPerDepartment() {
        Map<String, Optional<Employee>> perDept = emps.stream()
            .collect(Collectors.groupingBy(Employee::department,
                Collectors.maxBy(Comparator.comparingInt(Employee::age))));
        assertThat(perDept.get("TRADING").get().name()).isEqualTo("Amit");
        assertThat(perDept.get("RISK").get().name()).isEqualTo("Deepa");
    }

    @Test
    void emptyStreamReturnsEmpty() {
        Optional<Employee> result = List.<Employee>of().stream()
            .max(Comparator.comparingInt(Employee::age));
        assertThat(result).isEmpty();
    }
}
